def rearange_string(s):
    from collections import Counter
    c = Counter(s)
    if max(c.values()) > (len(s) + 1) // 2:
        return None
    ans = []
    max_val = max(c.values())
    max_char = max(c, key=c.get)
    for i in range(max_val):
        ans.append(max_char)
        c[max_char] -= 1
    for char, count in c.items():
        for _ in range(count):
            ans.append(char)
            c[char] -= 1
    return ''.join(ans)

